import heapq


def _ledger(data, revision_first, discounted):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_first:
            rank = (event.get("revision", 0), pos)
        else:
            rank = (seq, event.get("revision", 0), pos)
        if event_id not in chosen or rank > chosen[event_id][0]:
            chosen[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(num):
        return (num + 5000) // 10000 if mode == "half_up" else num // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = net if discounted else raw
        tax = rounded(base * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    options = {}
    rows = {}
    for name in names:
        valid = [r for r in packages[name]
                 if r["version"] not in blocked.get(name, [])]
        valid.sort(key=lambda r: r["version"], reverse=True)
        options[name] = [r["version"] for r in valid] + [None]
        rows[name] = {r["version"]: r for r in valid}

    for values in product(*(options[n] for n in names)):
        selected = dict(zip(names, values))
        if any(name not in selected or selected[name] is None or
               not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue
        if any(selected[name] is not None and selected[name] != version
               for name, version in pins.items()):
            continue

        closure = set()
        edges = {}
        pending = list(data["roots"])
        valid = True
        while pending and valid:
            name = pending.pop()
            version = selected.get(name)
            if version is None:
                valid = False
                break
            if name in closure:
                continue
            closure.add(name)
            row = rows[name][version]
            active = [dep for dep in row.get("deps", [])
                      if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in active:
                other = dep["name"]
                other_version = selected.get(other)
                if other_version is None or not dep["min"] <= other_version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not valid or closure != {n for n, v in selected.items() if v is not None}:
            continue

        visiting, finished = set(), set()
        def cyclic(name):
            if name in visiting:
                return True
            if name in finished:
                return False
            visiting.add(name)
            if any(cyclic(other) for other in edges.get(name, [])):
                return True
            visiting.remove(name)
            finished.add(name)
            return False

        if any(cyclic(name) for name in closure):
            continue
        return {"versions": {name: selected[name] for name in closure}}
    return {"error": "unsatisfiable"}


def _quota_intervals(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    best_value = None
    best_ids = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in data.get("quotas", {}).items()):
            continue
        active_ends = []
        compatible = True
        for job in sorted(chosen, key=lambda j: (j["start"], j["end"], j["id"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            if len(active_ends) >= 2:
                compatible = False
                break
            active_ends.append(job["end"])
        if not compatible:
            continue
        value = sum(job["value"] for job in chosen)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    dist = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            v = edge["v"]
            next_mask = mask | bit.get(v, 0)
            durations = [(edge["duration"], remaining)]
            if remaining:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in durations:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (v, next_mask, left)
                if next_time < dist.get(next_state, float("inf")):
                    dist[next_state] = next_time
                    heapq.heappush(queue, (next_time, v, next_mask, left))
    return {"arrival": None}


